import { lstat, readdir, readFile, unlink } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

// Only versioned artifacts generated by Cutline's own release process are
// eligible. This never touches installed apps, user profiles, or projects.
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const version = JSON.parse(await readFile(path.join(root, "package.json"), "utf8")).version;
const dryRun = process.argv.includes("--dry-run");
if (!/^\d+\.\d+\.\d+$/.test(version)) throw new Error("Invalid Cutline release version");
const desktop = path.join(root, "outputs", "desktop");
const output = path.join(root, "outputs");
const keep = [
  path.join(desktop, `Cutline-Setup-${version}-x64.exe`),
  path.join(desktop, `Cutline-Portable-${version}-x64.exe`),
];
for (const file of keep) {
  const info = await lstat(file);
  if (!info.isFile() || info.isSymbolicLink() || info.size < 1_000_000)
    throw new Error(`Replacement release is missing or incomplete: ${path.basename(file)}`);
}
const folders = [
  { dir: desktop, pattern: /^Cutline-(?:Setup|Portable)-(\d+\.\d+\.\d+)-x64\.exe(?:\.blockmap)?$/ },
  { dir: output, pattern: /^cutline-(\d+\.\d+\.\d+)-site\.tar$/ },
];
for (const { dir, pattern } of folders) {
  const entries = await readdir(dir, { withFileTypes: true });
  for (const entry of entries) {
    const match = pattern.exec(entry.name);
    if (!match || match[1] === version || !entry.isFile() || entry.isSymbolicLink()) continue;
    const target = path.resolve(dir, entry.name);
    if (path.dirname(target) !== dir) throw new Error(`Unsafe release path: ${entry.name}`);
    if (!dryRun) await unlink(target);
    console.log(`${dryRun ? "Would remove" : "Removed"} older Cutline release: ${entry.name}`);
  }
}
